import React, { useState } from "react";
import { Link, useNavigate } from "react-router-dom";
import { useAuth } from "../context/AuthContext";
import "../styles/auth.css";

const STEPS = ["Details", "Verify Email", "Trust Device", "Profile"];
const INTERESTS = ["Technology","Design","Gaming","Science","Photography","Startups","Music","Career","Sports","Art"];

function StepBar({ current }) {
  return (
    <div className="step-bar">
      {STEPS.map((s, i) => (
        <React.Fragment key={s}>
          <div className="step-item">
            <div className={`step-circle ${i < current ? "done" : i === current ? "active" : ""}`}>
              {i < current ? "✓" : i + 1}
            </div>
            <div className={`step-label ${i < current ? "done" : i === current ? "active" : ""}`}>{s}</div>
          </div>
          {i < STEPS.length - 1 && <div className={`step-line ${i < current ? "done" : ""}`} />}
        </React.Fragment>
      ))}
    </div>
  );
}

export default function SignUp() {
  const { signup, verifyEmail, resendOTP, updateProfile } = useAuth();
  const navigate = useNavigate();
  const [step,      setStep]      = useState(0);
  const [loading,   setLoading]   = useState(false);
  const [error,     setError]     = useState("");
  const [success,   setSuccess]   = useState("");
  const [userId,    setUserId]    = useState(null);
  const [trust,     setTrust]     = useState("session");
  const [pwVis,     setPwVis]     = useState(false);
  const [interests, setInterests] = useState([]);
  const [otp,       setOtp]       = useState(["","","","","",""]);
  const [form,      setForm]      = useState({ firstName:"", lastName:"", email:"", password:"", username:"", bio:"" });

  const set = (k, v) => setForm(f => ({ ...f, [k]: v }));

  const setOtpDigit = (i, v) => {
    const arr = [...otp]; arr[i] = v; setOtp(arr);
    if (v && i < 5) document.getElementById(`otp-${i+1}`)?.focus();
  };
  const otpBack = (e, i) => {
    if (e.key === "Backspace" && !otp[i] && i > 0) document.getElementById(`otp-${i-1}`)?.focus();
  };

  const pw = form.password;
  const pwChecks = { len: pw.length >= 8, upper: /[A-Z]/.test(pw), sym: /[0-9!@#$%^&*]/.test(pw) };
  const pwScore  = Object.values(pwChecks).filter(Boolean).length;
  const pwColor  = ["#ef4444","#f59e0b","#22c55e"][pwScore-1] || "#e5e7eb";

  const toggleInterest = (i) =>
    setInterests(s => s.includes(i) ? s.filter(x => x !== i) : s.length < 3 ? [...s, i] : s);

  /* ── Step 0: Details ─────────────────────────────────── */
  const handleStep0 = async () => {
    setError("");
    const { firstName, lastName, email, password, username } = form;
    if (!firstName || !lastName || !email || !password || !username)
      return setError("All fields are required.");
    if (!email.includes("@")) return setError("Enter a valid email.");
    if (password.length < 8)  return setError("Password must be at least 8 characters.");
    setLoading(true);
    try {
      const data = await signup({ firstName, lastName, email, password, username });
      setUserId(data.userId);
      setStep(1);
    } catch (e) { setError(e.response?.data?.message || "Signup failed. Try again."); }
    finally { setLoading(false); }
  };

  /* ── Step 1: Verify email OTP ────────────────────────── */
  const handleVerify = async () => {
    setError("");
    const code = otp.join("");
    if (code.length !== 6) return setError("Enter the full 6-digit code.");
    setLoading(true);
    try {
      await verifyEmail(userId, code);
      setStep(2);
    } catch (e) { setError(e.response?.data?.message || "Invalid code."); }
    finally { setLoading(false); }
  };

  const handleResend = async () => {
    setError(""); setSuccess("");
    try { await resendOTP(userId); setSuccess("New code sent to your email!"); } catch {}
  };

  /* ── Step 2: Trust device ─────────────────────────────── */
  const handleTrust = () => { setError(""); setStep(3); };

  /* ── Step 3: Profile ─────────────────────────────────── */
  const handleProfile = async () => {
    setLoading(true);
    try {
      await updateProfile({ bio: form.bio, interests, trustLevel: trust });
      navigate("/");
    } catch { navigate("/"); }
    finally { setLoading(false); }
  };

  return (
    <div className="auth-wrap">
      <div className="auth-card">
        <div className="auth-header">
          <div className="auth-logo">
            <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5"><circle cx="12" cy="12" r="10"/><path d="M8 9h8M8 12h6M8 15h4"/></svg>
            Echo
          </div>
          <div className="auth-tagline">Your community, your voice</div>
        </div>

        <div className="auth-tabs">
          <Link className="auth-tab" to="/signin">Sign In</Link>
          <div className="auth-tab active">Sign Up</div>
        </div>

        <div className="auth-body">
          <StepBar current={step} />

          {error   && <div className="alert alert-danger">{error}</div>}
          {success && <div className="alert alert-success">{success}</div>}

          {/* ── STEP 0 ─────────────────────────────────── */}
          {step === 0 && (<>
            <div className="field-row">
              <div className="field"><label>First name</label><input value={form.firstName} onChange={e=>set("firstName",e.target.value)} placeholder="Aria" autoFocus /></div>
              <div className="field"><label>Last name</label><input  value={form.lastName}  onChange={e=>set("lastName", e.target.value)} placeholder="Chen" /></div>
            </div>
            <div className="field"><label>Username</label><input value={form.username} onChange={e=>set("username",e.target.value)} placeholder="@username" /></div>
            <div className="field"><label>Email</label><input type="email" value={form.email} onChange={e=>set("email",e.target.value)} placeholder="you@example.com" /></div>
            <div className="field field-pw">
              <label>Password</label>
              <div style={{position:"relative"}}>
                <input type={pwVis?"text":"password"} value={form.password} onChange={e=>set("password",e.target.value)} placeholder="Min 8 characters" style={{paddingRight:36}} />
                <button type="button" className="pw-eye" onClick={()=>setPwVis(v=>!v)}>{pwVis?"🙈":"👁"}</button>
              </div>
              <div className="strength-bar"><div className="strength-fill" style={{width:`${(pwScore/3)*100}%`,background:pwColor}} /></div>
              <ul className="check-list">
                <li className={pwChecks.len  ?"ok":""}>{pwChecks.len  ?"✓":"○"} At least 8 characters</li>
                <li className={pwChecks.upper?"ok":""}>{pwChecks.upper?"✓":"○"} One uppercase letter</li>
                <li className={pwChecks.sym  ?"ok":""}>{pwChecks.sym  ?"✓":"○"} Number or symbol</li>
              </ul>
            </div>
            <div className="alert alert-info" style={{marginTop:8}}>📧 We'll send a 6-digit code to verify your email before you can post.</div>
            <button className="btn-main" onClick={handleStep0} disabled={loading}>{loading?"Creating account...":"Continue →"}</button>
            <div className="footer-link">Already have an account? <Link to="/signin">Sign in</Link></div>
          </>)}

          {/* ── STEP 1 ─────────────────────────────────── */}
          {step === 1 && (<>
            <div className="alert alert-success">✅ Verification code sent to <strong>{form.email}</strong></div>
            <div className="email-mock">
              <div className="from">FROM: noreply@echo.app</div>
              <div className="subject">Verify your Echo account</div>
              <div className="body">Hi {form.firstName},<br/>Use this code to verify your account:</div>
              <div className="code">••••••</div>
              <div className="note">⏱ Expires in 10 minutes. Never share this code.</div>
            </div>
            <label style={{fontSize:12,fontWeight:500,color:"#374151",display:"block",marginBottom:6}}>Enter 6-digit code from your email:</label>
            <div className="otp-row">
              {otp.map((d,i) => (
                <input key={i} id={`otp-${i}`} className="otp-d" maxLength={1} value={d}
                  onChange={e=>setOtpDigit(i,e.target.value)} onKeyDown={e=>otpBack(e,i)} autoFocus={i===0} />
              ))}
            </div>
            <button className="btn-main" onClick={handleVerify} disabled={loading}>{loading?"Verifying...":"Verify Email →"}</button>
            <button className="btn-ghost" onClick={handleResend}>Resend code</button>
            <button className="btn-ghost" onClick={()=>{setStep(0);setError("");}}>← Back</button>
          </>)}

          {/* ── STEP 2 ─────────────────────────────────── */}
          {step === 2 && (<>
            <div className="alert alert-success">✅ Email verified! Set your device trust level.</div>
            <div className="alert alert-info" style={{marginBottom:12}}>🔒 <strong>Context-based auth</strong> — we fingerprint this device. Choose how long to trust it for future sign-ins.</div>
            <div className="trust-options">
              {[
                {k:"session", icon:"🔒", title:"This session only",  desc:"You'll verify again next time you sign in from this device."},
                {k:"30d",     icon:"📅", title:"Trust for 30 days",  desc:"Skip verification on this device for 30 days."},
                {k:"always",  icon:"✅", title:"Always trust device", desc:"Permanently trusted — recommended for your personal device only."},
              ].map(({k,icon,title,desc}) => (
                <div key={k} className={`trust-opt ${trust===k?"selected":""}`} onClick={()=>setTrust(k)}>
                  <div className="trust-opt-icon">{icon}</div>
                  <div><div className="trust-opt-title">{title}</div><div className="trust-opt-desc">{desc}</div></div>
                </div>
              ))}
            </div>
            <button className="btn-main" onClick={handleTrust}>Continue →</button>
          </>)}

          {/* ── STEP 3 ─────────────────────────────────── */}
          {step === 3 && (<>
            <div className="alert alert-success">🎉 Almost done! Complete your profile.</div>
            <div className="field">
              <label>Bio <span className="opt">(optional)</span></label>
              <textarea value={form.bio} onChange={e=>set("bio",e.target.value)} placeholder="Tell the community about yourself..." rows={3} />
            </div>
            <div className="field">
              <label>Interests <span className="opt">(pick up to 3)</span></label>
              <div className="interest-wrap">
                {INTERESTS.map(i => (
                  <span key={i} className={`interest-tag ${interests.includes(i)?"sel":""}`} onClick={()=>toggleInterest(i)}>{i}</span>
                ))}
              </div>
            </div>
            <button className="btn-main" onClick={handleProfile} disabled={loading}>{loading?"Setting up...":"Create my account 🚀"}</button>
          </>)}
        </div>
      </div>
    </div>
  );
}
